import{G as e,K as t,n,ot as r}from"./chunks/framework.BZpZOnGD.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"documentalist-lab/review-and-reclassify/01-classification-audit.md","filePath":"documentalist-lab/review-and-reclassify/01-classification-audit.md"}`),a={name:`documentalist-lab/review-and-reclassify/01-classification-audit.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<div class="info custom-block"><p class="custom-block-title">🎬 The Story</p><p><em>The previous lab went well — <b>mostly</b></em>.</p><p><em>You uploaded 55 HR documents for your 5 employees to your personal folder. But in the rush to get everything in, a few mistakes crept in: one payslip ended up as a generic Document with no employee metadata, a contract was filed under the wrong class, a performance review has the wrong employee ID, a disciplinary record has no metadata at all, and an exit document is missing its DocType.</em></p><p><em>In a real repository with thousands of documents, these errors would be invisible — until someone searches for &quot;all payslips for your first employee&quot; and gets zero results, or a compliance audit finds documents with no retention metadata.</em></p><p><em>You ask Bob to run a classification audit on your namespace.</em></p></div><h2 id="🎯-what-you-will-learn" tabindex="-1">🎯 What You Will Learn <a class="header-anchor" href="#🎯-what-you-will-learn" aria-label="Permalink to “🎯 What You Will Learn”">​</a></h2><p>In this lab you will learn how to:</p><ul><li>Use Bob to <strong>search for documents</strong> with <strong>missing</strong> or <strong>incorrect metadata</strong>.</li><li>Ask Bob to <strong>read document content</strong> and reason about what class it should be.</li><li>Execute the <strong>reclassification workflow</strong>: <code>update_document_class</code> + <code>update_document_properties</code>.</li><li>Understand the <strong>risk of reclassification</strong> — what happens to properties when you change a document&#39;s class.</li><li>Produce a <strong>final governance health report</strong> for the repository.</li></ul><h2 id="🔧-mcp-tools-used" tabindex="-1">🔧 MCP Tools Used <a class="header-anchor" href="#🔧-mcp-tools-used" aria-label="Permalink to “🔧 MCP Tools Used”">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What It Does</th></tr></thead><tbody><tr><td><code>document_search</code></td><td>Finds documents matching specific criteria (missing properties, wrong class)</td></tr><tr><td><code>get_document_properties</code></td><td>Inspects the current state of a document</td></tr><tr><td><code>get_document_text_extract</code></td><td>Reads the document&#39;s text content for AI reasoning</td></tr><tr><td><code>update_document_class</code></td><td>Changes a document&#39;s class (e.g., Document → HRDocument)</td></tr><tr><td><code>update_document_properties</code></td><td>Updates metadata properties on a document</td></tr><tr><td><code>lookup_documents_by_name</code></td><td>Finds documents by name keywords</td></tr></tbody></table><h2 id="📋-the-situation" tabindex="-1">📋 The Situation <a class="header-anchor" href="#📋-the-situation" aria-label="Permalink to “📋 The Situation”">​</a></h2><p>You want Bob to find all HR documents in your namespace that are missing critical metadata — specifically, documents without an <code>EmployeeID</code> or with an obviously wrong one.</p><h2 id="💬-prompt-to-bob" tabindex="-1">💬 Prompt to Bob <a class="header-anchor" href="#💬-prompt-to-bob" aria-label="Permalink to “💬 Prompt to Bob”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">⚠️ Important</p><ul><li><p>Replace the example values below with your actual employee data from the script output.</p></li><li><p>Furthermore, keep the chat open and <strong>approve each step</strong> when prompted. Bob will ask for confirmation before e.g. invoking skills, executing commands and creating files.</p></li></ul></div><ol><li><p>Start a new task in IBM Bob by clicking the <code>+</code> sign on top of the Bob chat panel.</p></li><li><p>Next, click the <strong>+</strong> at the bottom left of the chat input, select <strong>Agent</strong> under <strong>Modes</strong>, and enter the following prompt:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to run a classification audit on my HR documents in namespace </span></span>
<span class="line"><span>/BOB_LAB/&lt;YOUR_LASTNAME&gt;/. Can you find all documents in the HRDocument </span></span>
<span class="line"><span>class that are missing an EmployeeID, or have an EmployeeID that doesn&#39;t </span></span>
<span class="line"><span>look right?</span></span></code></pre></div></li></ol><h2 id="🔍-what-bob-does-behind-the-scenes" tabindex="-1">🔍 What Bob Does Behind the Scenes <a class="header-anchor" href="#🔍-what-bob-does-behind-the-scenes" aria-label="Permalink to “🔍 What Bob Does Behind the Scenes”">​</a></h2><p>Bob activates the <code>hr-classification-workflow</code> skill and runs a two-pass audit against the IBM Content Cortex repository:</p><p><strong>Pass 1 — EmployeeID property check (HRDocument class)</strong></p><ul><li>Queries all <code>HRDocument</code> objects under <code>/BOB_LAB/&lt;LASTNAME&gt;/</code> using <code>INSUBFOLDER</code> containment.</li><li>Fetches the <code>EmployeeID</code> property for each document.</li><li>Validates each value against the expected pattern — first three characters of the last name (e.g. <code>DUP001</code>). Documents with an employee ID set to <code>null</code>, empty string, and <code>000000</code> are all treated as invalid.</li></ul><p><strong>Pass 2 — Class mismatch check (all Document objects)</strong></p><ul><li>Queries all <code>Document</code> objects (any class) under the same folder.</li><li>Client-side filters for documents whose name starts with the employee prefix (e.g. <code>DUP</code>).</li><li>Flags any document in that set that is <strong>not</strong> classified as <code>HRDocument</code>.</li></ul><p><strong>Final steps</strong></p><ul><li>Saves the combined results to <code>audit_results_{lastname}.json</code> for use by later phases (triage, fix, health report).</li><li>Prints a formatted summary table that relates to the initial prompt.</li></ul><h2 id="✅-expected-output-from-bob" tabindex="-1">✅ Expected Output from Bob <a class="header-anchor" href="#✅-expected-output-from-bob" aria-label="Permalink to “✅ Expected Output from Bob”">​</a></h2><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><hr><p>The audit found <strong>2 HRDocuments with missing or invalid EmployeeID</strong> in <code>/BOB_LAB/DUPONT/</code>:</p><table tabindex="0"><thead><tr><th>Document Name</th><th>EmployeeID Found</th><th>Issue</th><th>Document ID</th></tr></thead><tbody><tr><td><code>DUP003_Performance_Review_2024.txt</code></td><td><code>000000</code></td><td>Invalid value — all-zeros suffix</td><td><code>{A0F74DA0-0000-C726-9D54-7EA8136FB318}</code></td></tr><tr><td><code>DUP005_Exit_Notes.txt</code></td><td><em>(empty)</em></td><td>EmployeeID missing</td><td><code>{A0F74DB0-0000-C960-9D27-DDE560F9D71E}</code></td></tr></tbody></table><p><strong>2 HRDocument(s) with missing or invalid EmployeeID.</strong></p><p>The full audit results (including class mismatch data) have been saved to <code>audit_results_dupont.json</code> for later phases.</p><hr><p>Would you like to proceed? Here are the available next steps:</p><ul><li><strong>Fix EmployeeID issues</strong> — triage each document to extract the correct ID from its content, then apply the fix</li><li><strong>View class mismatches</strong> — the audit also found 3 documents under <code>/BOB_LAB/DUPONT/</code> that aren&#39;t classified as <code>HRDocument</code> at all</li><li><strong>Fix everything at once</strong> — bulk-remediate all 5 issues (2 property + 3 class)</li><li><strong>Generate a health report</strong> — produce a full classification health report for the namespace</li></ul></div><h2 id="💡-why-this-matters" tabindex="-1">💡 Why This Matters <a class="header-anchor" href="#💡-why-this-matters" aria-label="Permalink to “💡 Why This Matters”">​</a></h2><p>An <code>EmployeeID</code> of <code>000000</code> is a classic data quality problem — it looks like a valid value but is clearly a placeholder or error. Bob catches it because the audit checks the pattern, not just whether a value exists. The same applies to other common placeholders like <code>&quot;N/A&quot;</code>, <code>&quot;TBD&quot;</code>, or <code>&quot;unknown&quot;</code> that quietly accumulate over time.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};